// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 newVal) public {
        // lock in configuration before initialization
        vm.prank(address(0xA11CE));
        c.SetMinSum(0);
        // initialize the contract
        vm.prank(address(0xB0B));
        c.Initialized();
        // after initialization, SetMinSum must revert and MinSum must stay unchanged
        bool ok;
        vm.prank(address(0xA11CE));
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.MinSum() == 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount, address bogus) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        LogFile log = new LogFile();
        // set the real log file through SetLogFile, then init
        c.SetLogFile(address(log));
        c.Initialized();
        // now any further SetLogFile call reverts in both versions; observe via Put instead:
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) { ok = true; } catch { ok = false; }
        // Rule: once a LogFile has been registered via SetLogFile, deposits (Put)
        // succeed because events are logged to that file for every admissible input.
        assertTrue(ok);
    }
}

