pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 v1, uint256 v2, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(v1 != v2);
        // successful configuration call before initialization
        vm.prank(actor);
        c.SetMinSum(v1);
        // freeze configuration
        vm.prank(actor);
        c.Initialized();
        // any further SetMinSum must revert AND have no effect on MinSum
        vm.prank(actor);
        try c.SetMinSum(v2) {
            assertTrue(false, "expected revert");
        } catch {
            assertTrue(c.MinSum() == v1, "reverted call must not change MinSum");
        }
    }
}

